"kind": "propose",
"summary": "Liveness probe timeout is too short for the application's startup time",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Liveness probe timeout (2s) is shorter than the application's startup time (46s).",
    "supporting": ["probe_kills", "killed_during_startup", "crashed_on_its_own"],
    "contradicting": ["probe_timeouts"],
    "missing": ["container_logs_tail"],
    "status": "supported"
  },
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Liveness probe fails during startup due to strict timing.",
    "supporting": ["killed_during_startup", "probe_kills"],
    "contradicting": ["application_bug"],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "payments",
    "name": "payments-worker",
    "uid": "uid-deployment-payments-worker"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Increase liveness probe timeout to 5s, allowing the application to start before failing the probe.",
  "rationale": "The application takes 46s to start, but the liveness probe times out after 2s. Increasing the timeout to 5s would allow the application to respond before the probe fails. The evidence shows the probe fails with 'connection refused', indicating the app hasn't started listening yet. No application errors are present, so this is a probe timing issue, not a code bug. The fix aligns with the rollout history showing no recent changes to the probe configuration. The fix is needed because the probe kills the pod before it's ready, and the logs don't show any application errors or crashes that would be",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
  "cited_predicates": ["probe_kills", "killed_during_startup", "crashed_on_its_own", "probe_timeouts"]
}
}
